"""Labels for every generated file. R6's eval reads corpus/manifest.json."""

import json
from dataclasses import asdict, dataclass, field
from pathlib import Path

CORPUS_DIR = Path(__file__).resolve().parent.parent


@dataclass
class Item:
    id: str
    path: str  # relative to corpus/
    type: str  # "html" | "pdf"
    # "attack": hidden text aimed at an AI → must be flagged.
    # "hidden_benign": hidden text NOT aimed at an AI (e.g. keyword stuffing) → reported, not flagged.
    # "benign": nothing hidden on purpose → no flagged findings.
    label: str
    techniques: list[str] = field(default_factory=list)  # expected Technique values (core/src/types.ts)
    payload_kind: str = "none"  # "obvious" | "subtle" | "keyword_stuffing" | "none"
    description: str = ""

    @property
    def should_flag(self) -> bool:
        return self.label == "attack"


class Manifest:
    def __init__(self) -> None:
        self.items: list[Item] = []

    def add(self, item: Item) -> Item:
        if any(i.id == item.id for i in self.items):
            raise ValueError(f"duplicate corpus id: {item.id}")
        if not (CORPUS_DIR / item.path).exists():
            raise FileNotFoundError(f"{item.id}: {item.path} was not generated")
        self.items.append(item)
        return item

    def write(self) -> Path:
        out = CORPUS_DIR / "manifest.json"
        items = sorted(self.items, key=lambda i: i.id)
        data = {
            "description": "HiddenInk test corpus labels. Generated by corpus/generate.py; do not edit by hand.",
            "fields": {
                "label": "attack | hidden_benign | benign",
                "should_flag": "true only for attack: at least one flagged finding expected",
                "techniques": "expected techniques among the findings (flagged for attack, unflagged for hidden_benign)",
                "payload_kind": "obvious | subtle | keyword_stuffing | none",
            },
            "counts": {
                label: sum(1 for i in items if i.label == label) for label in ("attack", "hidden_benign", "benign")
            },
            "items": [{**asdict(i), "should_flag": i.should_flag} for i in items],
        }
        out.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        return out
